with base as (select id, name, email, country, is_active, age, lower(country) as country_lower, concat(city, ' - ', segment) as city_segment, coalesce(segment, 'N/A') as segment_clean from customers where signup_date >= date '2023-03-22' and country <> 'JP'), with_windows as (select id, name, email, country, is_active, age, country_lower, city_segment, segment_clean, row_number() over (partition by country order by age desc, id asc) as event_seq, ntile(4) over w_hist as age_bucket, first_value(age, true) over w_grp as first_known_age, sum(age) over (order by age asc, id asc rows between unbounded preceding and current row) as running_age, first_value(age) ignore nulls over w_grp as first_known_age_2 from base window w_hist as (partition by country order by age asc, id asc), w_grp as (partition by country order by age asc, id asc rows between unbounded preceding and current row)), deduped as (select * from with_windows qualify row_number() over (partition by country order by event_seq asc, id asc) = 1) select id, name, age, city_segment, age_bucket, first_known_age, running_age, first_known_age_2 from deduped;
